//! What angles-only initial orbit determination actually costs, measured on synthetic sightings.
//!
//! The three methods in [`spacelab_astro::iod`] are not interchangeable and the literature's ordering
//! of them is a statement about their derivations, not about their errors. This file measures the
//! errors: how Gauss degrades with the arc, how far past it Gooding gets, and where Gibbs and
//! Herrick–Gibbs swap places.
//!
//! The sightings are exact — generated by propagating a known state and pointing at it from a fixed
//! observer — so every number here is the method's own truncation and conditioning, with no
//! measurement noise in it. That is deliberate: noise would mask exactly the structure being measured.

#![allow(clippy::expect_used, clippy::float_cmp)]

use spacelab_astro::{
    IodError, Sighting, gauss, gibbs, herrick_gibbs, laplace, orbit_from_angles, propagate,
};
use spacelab_core::Vec3;

const MU: f64 = 3.986_004_418e14;

/// `SplitMix64` with a Box–Muller transform: a deterministic Gaussian source with no dependency, so
/// the noise experiment below reproduces bit for bit.
struct Gaussian {
    state: u64,
    spare: Option<f64>,
}

impl Gaussian {
    const fn seeded(seed: u64) -> Self {
        Self {
            state: seed,
            spare: None,
        }
    }

    fn uniform(&mut self) -> f64 {
        self.state = self.state.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.state;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^= z >> 31;
        // 53 significant bits mapped into (0, 1); the half-bit offset keeps the log below finite.
        #[allow(clippy::cast_precision_loss)]
        let mantissa = (z >> 11) as f64;
        (mantissa + 0.5) * (1.0 / 9_007_199_254_740_992.0)
    }

    fn normal(&mut self) -> f64 {
        if let Some(spare) = self.spare.take() {
            return spare;
        }
        let (u1, u2) = (self.uniform(), self.uniform());
        let radius = libm::sqrt(-2.0 * libm::log(u1));
        let angle = core::f64::consts::TAU * u2;
        self.spare = Some(radius * libm::sin(angle));
        radius * libm::cos(angle)
    }
}

/// A 700 km sun-synchronous orbit, and a ground observer that sees it.
///
/// The inclination matters: at 98.2° the angular momentum points south, so the transfer between the
/// first and last sighting runs the retrograde way round and [`orbit_from_angles`] has to be told so.
fn reference() -> (Vec3, Vec3, Vec3) {
    let r = Vec3::new(7_078_137.0, 0.0, 0.0);
    let speed = libm::sqrt(MU / r.norm());
    let inclination = 98.2_f64.to_radians();
    let v = Vec3::new(
        0.0,
        speed * libm::cos(inclination),
        speed * libm::sin(inclination),
    );
    (r, v, Vec3::new(4_000_000.0, 4_500_000.0, 1_500_000.0))
}

fn period(r: Vec3) -> f64 {
    core::f64::consts::TAU * libm::sqrt(libm::pow(r.norm(), 3.0) / MU)
}

/// Three exact sightings spanning `arc` seconds, centred on the middle epoch, and the true state
/// there.
fn synthesise(r0: Vec3, v0: Vec3, observer: Vec3, arc: f64) -> ([Sighting; 3], Vec3, Vec3) {
    let times = [-0.5 * arc, 0.0, 0.5 * arc];
    let states: [(Vec3, Vec3); 3] = core::array::from_fn(|i| propagate(r0, v0, MU, times[i]));
    let sightings = core::array::from_fn(|i| {
        let line = states[i].0 - observer;
        Sighting {
            time: times[i],
            line_of_sight: line.scale(1.0 / line.norm()),
            observer,
        }
    });
    (sightings, states[1].0, states[1].1)
}

/// Three sightings at arbitrary epochs: neither centred on zero nor evenly spaced.
fn at_epochs(r0: Vec3, v0: Vec3, observer: Vec3, times: [f64; 3]) -> ([Sighting; 3], Vec3, Vec3) {
    let states: [(Vec3, Vec3); 3] = core::array::from_fn(|i| propagate(r0, v0, MU, times[i]));
    let sightings = core::array::from_fn(|i| {
        let line = states[i].0 - observer;
        Sighting {
            time: times[i],
            line_of_sight: line.scale(1.0 / line.norm()),
            observer,
        }
    });
    (sightings, states[1].0, states[1].1)
}

/// The same three epochs, seen from a station the Earth carries round with it.
///
/// The observer is rotated about the pole at the IAU 2000 rate, so the triple carries a real `Ṙ`
/// and `R̈` instead of the exactly-zero ones a fixed vector gives.
fn from_a_turning_station(
    r0: Vec3,
    v0: Vec3,
    station: Vec3,
    times: [f64; 3],
) -> ([Sighting; 3], Vec3, Vec3) {
    const EARTH_RATE: f64 = 7.292_115e-5;
    let states: [(Vec3, Vec3); 3] = core::array::from_fn(|i| propagate(r0, v0, MU, times[i]));
    let sightings = core::array::from_fn(|i| {
        let angle = EARTH_RATE * times[i];
        let (sin, cos) = (libm::sin(angle), libm::cos(angle));
        let observer = Vec3::new(
            station.x * cos - station.y * sin,
            station.x * sin + station.y * cos,
            station.z,
        );
        let line = states[i].0 - observer;
        Sighting {
            time: times[i],
            line_of_sight: line.scale(1.0 / line.norm()),
            observer,
        }
    });
    (sightings, states[1].0, states[1].1)
}

/// The same three epochs, seen from a second satellite instead of from the ground.
///
/// A station's `R̈` is centripetal, `ω²|R| = 0.033` m/s². An observer in orbit has `R̈ = −μR/|R|³`,
/// which is 8.7 m/s² — 260 times larger — and it is `R̈` that `D₁ = L·(L̇ × R̈)` and hence
/// `p = −2D₁/D` are built from.
fn from_a_second_satellite(
    r0: Vec3,
    v0: Vec3,
    observer0: Vec3,
    observer_v0: Vec3,
    times: [f64; 3],
) -> ([Sighting; 3], Vec3, Vec3) {
    let states: [(Vec3, Vec3); 3] = core::array::from_fn(|i| propagate(r0, v0, MU, times[i]));
    let sightings = core::array::from_fn(|i| {
        let observer = propagate(observer0, observer_v0, MU, times[i]).0;
        let line = states[i].0 - observer;
        Sighting {
            time: times[i],
            line_of_sight: line.scale(1.0 / line.norm()),
            observer,
        }
    });
    (sightings, states[1].0, states[1].1)
}

/// `station` moved onto the target's orbit plane, then `out_of_plane` metres back off it.
fn beside_the_orbit_plane(r0: Vec3, v0: Vec3, station: Vec3, out_of_plane: f64) -> Vec3 {
    let h = r0.cross(v0);
    let normal = h.scale(1.0 / h.norm());
    station - normal.scale(normal.dot(station) - out_of_plane)
}

/// Every other test here samples at `[-a/2, 0, a/2]`, and that convenience hides two whole terms.
///
/// `t₂ = 0` makes `τ₁ = t₁ − t₂` and `τ₃ = t₃ − t₂` equal to `t₁` and `t₃`, so the subtraction that
/// forms them is not being tested at all — nor is Herrick–Gibbs's `d₃₂ = t₃ − t₂`. Even spacing is
/// worse: Herrick–Gibbs's middle coefficient carries a factor `(d₃₂ − d₂₁)`, which is *exactly* zero
/// on a centred triple, so the whole bracket it multiplies — the `1/(d₂₁d₃₂) + μ/(12r₂³)` that is the
/// method's entire correction at the middle point — can be rewritten arbitrarily without moving a
/// digit. An IOD routine is handed whatever epochs the observations carry, which are neither.
///
/// The numbers are this file's own measurement at `[100, 160, 340]` s on the reference orbit — a
/// 240 s arc, 4.1 % of the period, which puts Gauss between its 1 % and 5 % rows.
#[test]
fn the_methods_are_measured_at_epochs_that_are_neither_centred_nor_evenly_spaced() {
    let (r0, v0, observer) = reference();
    let times = [100.0, 160.0, 340.0];
    let (sightings, truth_r, truth_v) = at_epochs(r0, v0, observer, times);

    let (gauss_r, gauss_v) = gauss(&sightings, MU).expect("Gauss");
    let position = (gauss_r - truth_r).norm();
    let velocity = (gauss_v - truth_v).norm();
    // The velocity is Gauss's `f` and `g` series and nothing else — the position comes from the range
    // solution — and until this assertion existed the series could be rewritten term by term without
    // failing anything.
    assert!(
        libm::fabs(position - 1.571_676_712_113_744e4) <= 0.01 * 1.571_676_712_113_744e4,
        "Gauss position {position:e} m"
    );
    assert!(
        libm::fabs(velocity - 2.130_291_221_695_892e1) <= 0.01 * 2.130_291_221_695_892e1,
        "Gauss velocity {velocity:e} m/s"
    );

    let (gooding_r, gooding_v) = orbit_from_angles(&sightings, MU, false).expect("Gooding");
    assert!(
        (gooding_r - truth_r).norm() < 1e-6,
        "Gooding position {:e} m",
        (gooding_r - truth_r).norm()
    );
    assert!(
        (gooding_v - truth_v).norm() < 1e-8,
        "Gooding velocity {:e} m/s",
        (gooding_v - truth_v).norm()
    );

    // Laplace's Lagrange weights are where a centred triple hides the most. Every one of `first`
    // and `second` is built from differences against `t₂`, and at `t₂ = 0` half of them lose the
    // subtraction entirely — `t₁ − t₂` *is* `t₁`, so `+` and `−` are the same number and the sign
    // of the term is unobservable. Even spacing then makes `t₁ − t₂` and `t₂ − t₃` differ only in
    // sign, which collapses another pair. Measured here at 100/160/340 s, where neither holds.
    let (laplace_r, laplace_v) = laplace(&sightings, MU).expect("Laplace");
    let laplace_position = (laplace_r - truth_r).norm();
    let laplace_velocity = (laplace_v - truth_v).norm();
    assert!(
        libm::fabs(laplace_position - 2.700_092_009_154_902_2e4)
            <= 0.01 * 2.700_092_009_154_902_2e4,
        "Laplace position {laplace_position:e} m"
    );
    assert!(
        libm::fabs(laplace_velocity - 4.769_672_057_269_609_7e2)
            <= 0.01 * 4.769_672_057_269_609_7e2,
        "Laplace velocity {laplace_velocity:e} m/s"
    );

    let states: [(Vec3, Vec3); 3] = core::array::from_fn(|i| propagate(r0, v0, MU, times[i]));
    let series = herrick_gibbs(
        states[0].0,
        states[1].0,
        states[2].0,
        times[0],
        times[1],
        times[2],
        MU,
    )
    .expect("Herrick-Gibbs");
    let series_error = (series - states[1].1).norm();
    assert!(
        libm::fabs(series_error - 2.966_494_685_100_139e-2) <= 0.01 * 2.966_494_685_100_139e-2,
        "Herrick-Gibbs {series_error:e} m/s"
    );
    // Gibbs is exact algebra and this arc is wide enough for it, so it sits at the rounding floor
    // rather than at a truncation. A band would pin noise; the bound is what the method promises.
    let exact = gibbs(states[0].0, states[1].0, states[2].0, MU).expect("Gibbs");
    assert!(
        (exact - states[1].1).norm() < 1e-8,
        "Gibbs {:e} m/s",
        (exact - states[1].1).norm()
    );
}

/// The observer stands still in every other test here, and that zeroes two of Laplace's terms.
///
/// `laplace` builds `Ṙ` and `R̈` from the same Lagrange weights it applies to the lines of sight.
/// Hand it one observer vector three times and both come out **exactly zero**, and with them
/// `D₁ = L·(L̇ × R̈)` and `D₃ = L·(L̈ × R̈)` — so `p = −2D₁/D` is `−0.0` and every operator in
/// `c₆ = −(p² + 2(L·R)p + R²)` is arithmetic on zero. `p * p` and `p + p` are the same number;
/// `2(L·R)p`, `(2 + L·R)p` and `(2/(L·R))p` are all zero. Seven of `laplace`'s surviving mutants sat
/// in those two lines and none of them could move an answer computed from a fixed station.
///
/// A station on the ground is not fixed: it turns with the Earth at 7.292 115e-5 rad/s, which over
/// this 240 s arc carries it 116 km. That is the term Laplace's derivation has and Gauss's does not,
/// and this is the only test that supplies it.
#[test]
fn laplace_is_given_an_observer_that_moves() {
    let (r0, v0, station) = reference();
    let times = [100.0, 160.0, 340.0];
    let (sightings, truth_r, truth_v) = from_a_turning_station(r0, v0, station, times);
    let (r, v) = laplace(&sightings, MU).expect("Laplace");
    let position = (r - truth_r).norm();
    let velocity = (v - truth_v).norm();
    assert!(
        libm::fabs(position - 4.888_075_363_542_038_4e4) <= 0.01 * 4.888_075_363_542_038_4e4,
        "Laplace position {position:e} m"
    );
    assert!(
        libm::fabs(velocity - 4.616_048_074_480_463_6e2) <= 0.01 * 4.616_048_074_480_463_6e2,
        "Laplace velocity {velocity:e} m/s"
    );

    // And the observer really is moving: the same triple with the station frozen at its middle
    // position is a different answer, which is what says the R-terms reached the result at all.
    let frozen = at_epochs(r0, v0, sightings[1].observer, times).0;
    let (frozen_r, _) = laplace(&frozen, MU).expect("Laplace, frozen station");
    assert!(
        (frozen_r - r).norm() > 1e3,
        "freezing the station moved the answer by only {:e} m, so Ṙ and R̈ are not reaching it",
        (frozen_r - r).norm()
    );
}

/// A turning station moves `R̈` off zero; it does not move `p` anywhere near `|R|`.
///
/// `ρ = p + q/r³` splits the range into the part the observer's own acceleration accounts for and
/// the part the target's gravity does. From the turning ground station `p` is −2.6e4 m against an
/// `|R|` of 6.2e6, so in `c₆ = −(p² + 2(L·R)p + R²)` the `p²` term is 1.7e-5 of `R²` and writing it
/// `p + p` instead moves `c₆` by that much — well inside the 1 % those tests assert to. The
/// neighbouring `2(L·R)p` is three orders larger and its own mutants do die there.
///
/// An observer that is itself in orbit is the case where the `p²` term is the equation. Here `p`
/// comes out 9.3e7 m, fourteen times `|R|`, and `p²` is 8.6e15 against an `R²` of 4.6e13.
/// The method is worse off for it: 189 km against the 49 km the same arc gives from the ground,
/// because `q/r³` has to cancel that `p` to leave a range of a few hundred kilometres, and the
/// cancellation costs seven digits. That is the measurement, not a defect — it is why a space-based
/// angles-only fix wants Gooding and an initial range guess rather than Laplace.
#[test]
fn laplace_is_given_an_observer_in_orbit() {
    let (r0, v0, _) = reference();
    let times = [100.0, 160.0, 340.0];
    let observer0 = Vec3::new(0.0, 6_778_137.0, 0.0);
    let observer_v0 = Vec3::new(-libm::sqrt(MU / observer0.norm()), 0.0, 0.0);
    let (sightings, truth_r, truth_v) =
        from_a_second_satellite(r0, v0, observer0, observer_v0, times);
    let (r, v) = laplace(&sightings, MU).expect("Laplace from orbit");
    let position = (r - truth_r).norm();
    let velocity = (v - truth_v).norm();
    assert!(
        libm::fabs(position - 1.889_372_099_745_778_8e5) <= 0.01 * 1.889_372_099_745_778_8e5,
        "Laplace position {position:e} m"
    );
    assert!(
        libm::fabs(velocity - 3.545_705_671_133_347_3e2) <= 0.01 * 3.545_705_671_133_347_3e2,
        "Laplace velocity {velocity:e} m/s"
    );
}

/// The range scan starts at 1 % of `|R|`, and every other test here looks *up*.
///
/// `laplace` brackets the root of `r⁸ + c₆r⁶ + c₃r³ + c₀` on `[0.01|R|, 1000|R|]`, which is a
/// fraction and a multiple of the observer's own radius rather than two absolute distances. From
/// the ground, and from the 6 778 km observer above, the target is always further out than the
/// observer, so a lower bracket end of `0.01|R|` and one of `|R|` itself would both work and the
/// fraction is doing nothing observable.
///
/// A sensor looking *down* is the case that needs it. Put the observer at 1 200 km and the target at
/// 700 km and `r = 7.078e6` is below `|R| = 7.578e6`: the scan has to start below the observer's own
/// radius to bracket the root at all.
#[test]
fn laplace_is_given_a_target_below_the_observer() {
    let (r0, v0, _) = reference();
    let times = [100.0, 160.0, 340.0];
    let observer0 = Vec3::new(0.0, 7_578_137.0, 0.0);
    let observer_v0 = Vec3::new(-libm::sqrt(MU / observer0.norm()), 0.0, 0.0);
    let (sightings, truth_r, _) = from_a_second_satellite(r0, v0, observer0, observer_v0, times);
    assert!(
        truth_r.norm() < sightings[1].observer.norm(),
        "the target has to be the lower of the two for this test to mean anything"
    );
    let (r, _) = laplace(&sightings, MU).expect("Laplace looking down");
    let position = (r - truth_r).norm();
    assert!(
        libm::fabs(position - 2.057_972_621_585_969_2e5) <= 0.01 * 2.057_972_621_585_969_2e5,
        "Laplace position {position:e} m"
    );
}

/// An observer in the target's orbit plane is Laplace's own degeneracy, and the guard for it has to
/// be scale-free.
///
/// Put the station in the plane and every line of sight lies in that plane too, so `L`, `L̇` and `L̈`
/// are coplanar and `D = 2 L·(L̇ × L̈)` — the determinant every range in the method is divided by — is
/// zero. `laplace` rejects on the *normalised* triple product, `L·(L̇ × L̈)` over `|L̇||L̈|`, which is
/// a sine and therefore comparable against a fixed 1e-12.
///
/// The normalisation is the thing worth a test, because the two magnitudes it divides by are nowhere
/// near each other: on this geometry `|L̇| = 2.45e-3` rad/s and `|L̈| = 6.07e-6` rad/s². A centimetre
/// off the plane is a sine of 1.4e-9, a thousand times the threshold, and the method solves it to
/// 41.8 km. The same geometry read through the *un*-normalised triple product is 2.1e-17, and
/// through a sum `|L̇| + |L̈|` instead of a product it is 8.6e-15 — both below 1e-12, so either
/// version of the divisor rejects a triple that is not degenerate at all.
#[test]
fn the_degeneracy_guard_is_a_sine_and_not_a_volume() {
    let (r0, v0, station) = reference();
    let times = [100.0, 160.0, 340.0];

    let inside = beside_the_orbit_plane(r0, v0, station, 0.0);
    let (coplanar, ..) = at_epochs(r0, v0, inside, times);
    let error = laplace(&coplanar, MU).expect_err("an observer in the orbit plane is degenerate");
    let IodError::DegenerateGeometry { triple_product } = error else {
        panic!("expected DegenerateGeometry, got {error:?}");
    };
    assert!(
        libm::fabs(triple_product) <= 1.0,
        "the payload is a sine, so it cannot exceed one: {triple_product:e}"
    );

    let beside = beside_the_orbit_plane(r0, v0, station, 0.01);
    let (sightings, truth_r, _) = at_epochs(r0, v0, beside, times);
    let (r, _) = laplace(&sightings, MU).expect("a centimetre out of the plane is not degenerate");
    let position = (r - truth_r).norm();
    assert!(
        libm::fabs(position - 4.175_001_857_196_884_5e4) <= 0.01 * 4.175_001_857_196_884_5e4,
        "Laplace position {position:e} m"
    );
}

/// A 0.3-eccentricity orbit sampled either side of perigee, and a station that can see it.
///
/// Everything else in this file runs on the circular reference orbit, where `|r₁| = |r₂| = |r₃|` to
/// eleven digits. Gibbs's `S = r₁(|r₂| − |r₃|) + r₂(|r₃| − |r₁|) + r₃(|r₁| − |r₂|)` is built entirely
/// out of those differences, so on a circular orbit it is numerically zero and the whole term can be
/// rewritten — signs flipped, the vector dropped from the final sum — without moving a digit of the
/// answer. `S` is what carries the radial motion, and an orbit with no radial motion cannot test it.
fn eccentric() -> (Vec3, Vec3, Vec3) {
    let perigee = 7_000_000.0;
    let semi_major = 10_000_000.0;
    let r = Vec3::new(perigee, 0.0, 0.0);
    let speed = libm::sqrt(MU * (2.0 / perigee - 1.0 / semi_major));
    let inclination = 30.0_f64.to_radians();
    let v = Vec3::new(
        0.0,
        speed * libm::cos(inclination),
        speed * libm::sin(inclination),
    );
    (r, v, Vec3::new(3_000_000.0, -5_500_000.0, 2_500_000.0))
}

/// The three position-vector methods on an orbit whose radius actually changes.
///
/// Radii 7 291 834 m, 7 048 453 m and 7 865 107 m over the 1 400 s triple — a 12 % spread against the
/// circular orbit's zero — so `S` is a real vector and Gibbs's exactness has something to be exact
/// about. It reaches 1.3e-12 m/s here, four orders better than on the circular arc of comparable
/// width, because the conditioning improves as the three positions stop being interchangeable.
/// Herrick–Gibbs is 142 m/s off over the same triple, which is the truncation it promises on an arc
/// this wide and not a defect.
#[test]
fn the_position_vector_methods_are_measured_on_an_eccentric_orbit() {
    let (r0, v0, observer) = eccentric();
    let times = [-500.0, 200.0, 900.0];
    let states: [(Vec3, Vec3); 3] = core::array::from_fn(|i| propagate(r0, v0, MU, times[i]));

    let spread = (states[2].0.norm() - states[1].0.norm()) / states[1].0.norm();
    assert!(spread > 0.1, "the sample is not eccentric enough: {spread}");

    let exact = gibbs(states[0].0, states[1].0, states[2].0, MU).expect("Gibbs");
    assert!(
        (exact - states[1].1).norm() < 1e-9,
        "Gibbs {:e} m/s",
        (exact - states[1].1).norm()
    );

    let series = herrick_gibbs(
        states[0].0,
        states[1].0,
        states[2].0,
        times[0],
        times[1],
        times[2],
        MU,
    )
    .expect("Herrick-Gibbs");
    let series_error = (series - states[1].1).norm();
    assert!(
        libm::fabs(series_error - 1.422_436_739_215_629e2) <= 0.01 * 1.422_436_739_215_629e2,
        "Herrick-Gibbs {series_error:e} m/s"
    );

    // The angles-only pair on the same orbit, prograde this time — a 30° inclination runs the other
    // way round from the reference orbit's 98.2°, so the transfer sense is the opposite one.
    let sightings: [Sighting; 3] = core::array::from_fn(|i| {
        let line = states[i].0 - observer;
        Sighting {
            time: times[i],
            line_of_sight: line.scale(1.0 / line.norm()),
            observer,
        }
    });
    let (gauss_r, _) = gauss(&sightings, MU).expect("Gauss");
    let gauss_error = (gauss_r - states[1].0).norm();
    assert!(
        libm::fabs(gauss_error - 5.691_017_588_374_704e5) <= 0.01 * 5.691_017_588_374_704e5,
        "Gauss {gauss_error:e} m"
    );
    let (gooding_r, gooding_v) = orbit_from_angles(&sightings, MU, true).expect("Gooding");
    assert!(
        (gooding_r - states[1].0).norm() < 1e-6 && (gooding_v - states[1].1).norm() < 1e-9,
        "Gooding {:e} m, {:e} m/s",
        (gooding_r - states[1].0).norm(),
        (gooding_v - states[1].1).norm()
    );
}

/// The table in the [`spacelab_astro::iod`] module documentation, regenerated.
///
/// Gauss is a seed and Gooding is an answer, and the gap between them is four to eleven orders of
/// magnitude depending on the arc. Neither bound is a round number chosen for comfort: each is the
/// worst case of the sweep, printed by this test.
#[test]
fn the_accuracy_table_in_the_module_documentation_still_holds() {
    let (r0, v0, observer) = reference();
    let expected: [(f64, f64, f64); 5] = [
        // arc fraction, Gauss position error (m), Gooding position error (m)
        (0.001, 1.008_914_833_669_506e1, 3.178_031_960_241_467e-4),
        (0.01, 1.009_187_298_423_589_6e3, 1.217_579_841_273_296_7e-6),
        (0.05, 2.534_384_057_642_184_8e4, 1.604_431_640_594_762e-8),
        (0.10, 1.028_421_378_684_040_1e5, 2.797_519_286_785_601e-7),
        (0.25, 7.200_022_313_657_516e5, 1.455_191_522_836_685_2e-9),
    ];
    for (fraction, gauss_want, gooding_want) in expected {
        let (sightings, truth_r, truth_v) = synthesise(r0, v0, observer, fraction * period(r0));
        let gauss_error = (gauss(&sightings, MU).expect("Gauss").0 - truth_r).norm();
        let (r, v) = orbit_from_angles(&sightings, MU, false).expect("Gooding");
        let gooding_error = (r - truth_r).norm();

        // A percent band, not equality: the numbers are a record of what the methods do, and pinning
        // them to the ulp would turn a change in the last digit of a Stumpff series into a failure.
        assert!(
            libm::fabs(gauss_error - gauss_want) <= 0.01 * gauss_want,
            "arc {fraction}: Gauss {gauss_error:e} m against the documented {gauss_want:e}"
        );
        assert!(
            libm::fabs(gooding_error - gooding_want) <= 0.01 * gooding_want,
            "arc {fraction}: Gooding {gooding_error:e} m against the documented {gooding_want:e}"
        );
        // The velocity is the half of the state Gauss is worst at and nothing above checks.
        let velocity_error = (v - truth_v).norm();
        assert!(
            velocity_error < 1e-4,
            "arc {fraction}: Gooding velocity off by {velocity_error:e} m/s"
        );
    }
}

/// Three sightings spanning `arc`, with each direction tilted by two independent Gaussian errors.
///
/// The tilt is applied in the plane perpendicular to the true direction and the result renormalised,
/// which is what an astrometric error *is* — two angles, no range. Perturbing the Cartesian
/// components instead would put error along the line of sight, where a telescope has none.
fn noisy(
    r0: Vec3,
    v0: Vec3,
    observer: Vec3,
    arc: f64,
    sigma: f64,
    noise: &mut Gaussian,
) -> ([Sighting; 3], Vec3) {
    let times = [-0.5 * arc, 0.0, 0.5 * arc];
    let states: [(Vec3, Vec3); 3] = core::array::from_fn(|i| propagate(r0, v0, MU, times[i]));
    let sightings = core::array::from_fn(|i| {
        let line = states[i].0 - observer;
        let direction = line.scale(1.0 / line.norm());
        let seed =
            if direction.x.abs() <= direction.y.abs() && direction.x.abs() <= direction.z.abs() {
                Vec3::new(1.0, 0.0, 0.0)
            } else if direction.y.abs() <= direction.z.abs() {
                Vec3::new(0.0, 1.0, 0.0)
            } else {
                Vec3::new(0.0, 0.0, 1.0)
            };
        let across = direction.cross(seed);
        let across = across.scale(1.0 / across.norm());
        let along = direction.cross(across);
        let tilted =
            direction + across.scale(sigma * noise.normal()) + along.scale(sigma * noise.normal());
        Sighting {
            time: times[i],
            line_of_sight: tilted.scale(1.0 / tilted.norm()),
            observer,
        }
    });
    (sightings, states[1].0)
}

/// Laplace against Gauss and Gooding on identical exact sightings — the ticket's own question.
///
/// The literature files Laplace as the worse of the two classical methods, and #285 was written not
/// to merge it on parity grounds. It earns its place on a measurement instead: its position error
/// crosses below Gauss's at long arc, and its velocity error never does.
#[test]
fn the_laplace_row_of_the_accuracy_table_still_holds() {
    let (r0, v0, observer) = reference();
    let expected: [(f64, f64, f64); 5] = [
        // arc fraction, Laplace position error (m), Laplace velocity error (m/s)
        (0.001, 1.231_762_144_137_469_4e1, 2.622_504_091_470_048_4e-2),
        (0.01, 1.231_309_584_883_178_6e3, 2.621_636_521_340_984e0),
        (0.05, 3.051_216_479_368_305e4, 6.501_797_511_541_172e1),
        (0.10, 1.188_261_202_401_753_8e5, 2.537_109_641_630_624_4e2),
        (0.25, 6.340_211_763_104_064e5, 1.354_120_744_396_621e3),
    ];
    for (fraction, position_want, velocity_want) in expected {
        let (sightings, truth_r, truth_v) = synthesise(r0, v0, observer, fraction * period(r0));
        let (r, v) = laplace(&sightings, MU).expect("Laplace");
        let position = (r - truth_r).norm();
        let velocity = (v - truth_v).norm();
        assert!(
            libm::fabs(position - position_want) <= 0.01 * position_want,
            "arc {fraction}: Laplace {position:e} m against the documented {position_want:e}"
        );
        assert!(
            libm::fabs(velocity - velocity_want) <= 0.01 * velocity_want,
            "arc {fraction}: Laplace {velocity:e} m/s against the documented {velocity_want:e}"
        );

        // The velocity is where the overtake stops. Laplace's is worse at every arc, by 1.96× at the
        // shortest and 2.50× at the longest — including at 25 %, where its *position* is 12 %
        // better. A method that wins on half the state is not a better estimate of the state.
        let (_, gauss_v) = gauss(&sightings, MU).expect("Gauss");
        let ratio = velocity / (gauss_v - truth_v).norm();
        assert!(
            (1.9..2.6).contains(&ratio),
            "arc {fraction}: Laplace velocity is {ratio}× Gauss's, outside the measured 1.96–2.50"
        );
    }
}

/// Where Laplace overtakes Gauss, bracketed by a sweep rather than quoted from a book.
///
/// Both are second order in the arc, so which one wins is decided by the coefficient and by how the
/// order drifts — fitted slopes rise past two for Gauss (2.000, 2.003, 2.021, 2.124) and fall below
/// it for Laplace (2.000, 1.995, 1.961, 1.827). Gauss starts 20 % lower and is caught.
#[test]
fn laplace_overtakes_gauss_only_past_a_fifth_of_a_period() {
    let (r0, v0, observer) = reference();
    let mut previous: Option<(f64, bool)> = None;
    let mut crossover = None;
    for step in 0..40 {
        // 5 % to 40 % of a period, geometric.
        let fraction = 0.05 * libm::pow(8.0, f64::from(step) / 39.0);
        let (sightings, truth, _) = synthesise(r0, v0, observer, fraction * period(r0));
        let gauss_error = (gauss(&sightings, MU).expect("Gauss").0 - truth).norm();
        let laplace_error = (laplace(&sightings, MU).expect("Laplace").0 - truth).norm();
        let laplace_wins = laplace_error < gauss_error;
        if let Some((last, false)) = previous
            && laplace_wins
        {
            crossover = Some((last, fraction));
        }
        previous = Some((fraction, laplace_wins));
    }

    let (below, above) = crossover.expect("the sweep never crossed over");
    // Measured: Gauss is the better of the two below 18.96 % of a period and Laplace above 20.00 %.
    // One step of the sweep, so this brackets rather than locates.
    assert!(
        (0.18..0.19).contains(&below) && (0.19..0.21).contains(&above),
        "crossover bracketed between {below} and {above} of a period, outside the measured window"
    );
}

/// On a short noisy arc the two classical methods are a tie, which is not what the literature says.
///
/// The received claim is that Laplace's second derivative amplifies measurement error and is
/// therefore the worse choice on a short arc. Paired over 2 000 trials on *identical* noisy
/// sightings — the pairing is what makes 2 000 enough, since both methods see the same errors — it
/// is not: Laplace has the smaller position error in 49.0 % of pairs at 0.5 % of a period and 48.8 %
/// at 1 %, a coin flip to within the 1.1 percentage-point standard error. The reason is that neither
/// method's truncation is what is being measured: at 1 % of a period Gauss's is 1 km and one
/// arcsecond of angular error is 18 km.
///
/// By 5 % the truncation is back in charge and the ordering is the noiseless one, decisively.
#[test]
fn on_a_short_noisy_arc_laplace_and_gauss_are_a_tie_and_at_five_percent_they_are_not() {
    const TRIALS: usize = 2_000;
    let (r0, v0, observer) = reference();
    let sigma = (1.0 / 3600.0_f64).to_radians();

    let win_rate = |fraction: f64| {
        let mut noise = Gaussian::seeded(20_260_815);
        let (mut wins, mut pairs) = (0usize, 0usize);
        for _ in 0..TRIALS {
            let (sightings, truth) =
                noisy(r0, v0, observer, fraction * period(r0), sigma, &mut noise);
            if let (Ok((a, _)), Ok((b, _))) = (gauss(&sightings, MU), laplace(&sightings, MU)) {
                pairs += 1;
                if (b - truth).norm() < (a - truth).norm() {
                    wins += 1;
                }
            }
        }
        assert!(pairs > TRIALS * 9 / 10, "{pairs} usable pairs of {TRIALS}");
        #[allow(clippy::cast_precision_loss)]
        let rate = wins as f64 / pairs as f64;
        rate
    };

    for fraction in [0.005, 0.01] {
        let rate = win_rate(fraction);
        assert!(
            (0.45..0.55).contains(&rate),
            "arc {fraction}: Laplace wins {rate} of pairs, which is not a tie — the classical claim \
             that a derivative estimator is the worse choice on a short noisy arc would put this \
             well below 0.45"
        );
    }
    let five_percent = win_rate(0.05);
    assert!(
        five_percent < 0.05,
        "arc 0.05: Laplace wins {five_percent} of pairs; past the noise-dominated regime the \
         noiseless ordering should reassert itself and it is Gauss's"
    );
}

/// Gauss's order is fitted, not assumed.
///
/// The first term its `f` and `g` series drop is cubic in the arc, and quoting that as the error
/// order is the obvious mistake — this test was written asserting it and measured 100.03× the error
/// for 10× the arc. The truncation reaches the answer through a range solution whose sensitivity
/// carries an inverse power of the arc, and one of the three cancels.
#[test]
fn the_gauss_error_grows_as_the_square_of_the_arc() {
    let (r0, v0, observer) = reference();
    let error = |fraction: f64| {
        let (sightings, truth, _) = synthesise(r0, v0, observer, fraction * period(r0));
        (gauss(&sightings, MU).expect("Gauss").0 - truth).norm()
    };
    let fractions = [0.001, 0.01, 0.05, 0.10, 0.25];
    let errors = fractions.map(error);
    // Measured slopes: 2.000, 2.003, 2.021, 2.124. The drift is the series' next term coming into
    // range as the arc opens, which is why the band has to reach past two.
    for i in 1..fractions.len() {
        let slope =
            libm::log(errors[i] / errors[i - 1]) / libm::log(fractions[i] / fractions[i - 1]);
        assert!(
            (1.95..2.20).contains(&slope),
            "arc {} to {}: slope {slope}",
            fractions[i - 1],
            fractions[i]
        );
    }
}

/// Where Gibbs and Herrick–Gibbs swap places, measured rather than quoted.
///
/// Gibbs is exact algebra on three coplanar positions and Herrick–Gibbs is a truncated Taylor series,
/// so the naive ordering says Gibbs always wins. It does not: Gibbs divides by cross products that
/// vanish as the three positions become collinear, and on a short arc that cancellation costs more
/// than Herrick–Gibbs's truncation does. The crossover is a property of the geometry and the
/// arithmetic, not of the algebra, so the only way to know where it is is to walk it.
#[test]
fn gibbs_and_herrick_gibbs_swap_places_at_a_measurable_transfer_angle() {
    let (r0, v0, _) = reference();
    let period = period(r0);

    let mut crossover = None;
    let mut previous: Option<(f64, bool)> = None;
    for step in 0..48 {
        // 0.02 % to 20 % of a period, geometric, which is how the conditioning varies.
        let fraction = 2e-4 * libm::pow(1000.0, f64::from(step) / 47.0);
        let arc = fraction * period;
        let times = [-0.5 * arc, 0.0, 0.5 * arc];
        let states: [(Vec3, Vec3); 3] = core::array::from_fn(|i| propagate(r0, v0, MU, times[i]));
        let angle = libm::acos(
            (states[0].0.dot(states[2].0) / (states[0].0.norm() * states[2].0.norm()))
                .clamp(-1.0, 1.0),
        );

        let exact =
            (gibbs(states[0].0, states[1].0, states[2].0, MU).expect("Gibbs") - states[1].1).norm();
        let series = (herrick_gibbs(
            states[0].0,
            states[1].0,
            states[2].0,
            times[0],
            times[1],
            times[2],
            MU,
        )
        .expect("Herrick-Gibbs")
            - states[1].1)
            .norm();

        let gibbs_wins = exact < series;
        if let Some((last_angle, false)) = previous
            && gibbs_wins
        {
            crossover = Some((last_angle.to_degrees(), angle.to_degrees()));
        }
        previous = Some((angle, gibbs_wins));
    }

    let (below, above) = crossover.expect("the sweep never crossed over");
    // Measured: Herrick–Gibbs is the better of the two below this angle and Gibbs above it. The
    // interval is one step of the sweep, so it brackets rather than locates.
    assert!(
        (0.2..3.0).contains(&below) && (0.2..3.0).contains(&above),
        "crossover bracketed between {below}° and {above}°, outside the expected decade"
    );
    assert!(above > below, "the bracket is inverted");
}
